stringi_189 <- function(lib) {
  desc <- file.path(lib, "stringi", "DESCRIPTION")
  if (!file.exists(desc)) return(FALSE)
  any(grepl("^Version:[[:space:]]*1\\.8\\.9[[:space:]]*$", readLines(desc, warn = FALSE)))
}
